+fn excess_delivery_amount_is_an_explicit_source_correspondence_limit() {
+    let p = parse(SOURCE).unwrap();
+    let a = artifact(&p);
+    let mut s = fixture("complete");
+    s.liabilities
+        .iter_mut()
+        .find(|l| l.name == "delivery")
