+        e.post
+            .liabilities
+            .iter()
+            .find(|l| l.name == "delivery")
+            .unwrap()
+            .amount,
+        UInt(1)
+    );
+    assert_eq!(e.post.state["remaining"], Value::UInt(UInt(0)));
+    let c = circuit(&a, "complete");
+    // Honest compilation has the same limitation: no source expression can
+    // assert that this incoming duty equals the supplied remaining state.
+    assert!(check(c, &public_values(c, &s, &e)));
